insert into public.products (id, name, conc, gender, family, tagline, description, notes, longevity, sillage, sizes, sample, look, badge, rank, added, stock, images, inspired) values ('safrane', 'Safrane', 'EDP', 'unisex', 'ambros', 'Šafranas, jazminas ir ambra', 'Spindintis ambros ir medienos kvapas. Šafranas ir jazminas susilieja su ambrine mediena ir ambra, o eglės sakai ir kedras suteikia jam oro, šviesos ir išskirtinio, ilgai išliekančio šleifo. Kvapas, kurį pastebi kiti.', '{"top":["Šafranas","Jazminas"],"heart":["Ambrinė mediena","Ambra"],"base":["Eglės sakai","Kedras"]}'::jsonb, 5, 5, '[{"ml":33,"price":29.9},{"ml":100,"price":59.9}]'::jsonb, 3.9, '{"liquid":"#C0574A","tint":"#F6E6E1","cap":"gold","shape":"rect"}'::jsonb, 'Naujiena', 2, '2026-11-01', null, array['img/kvapai/safrane-1.webp']::text[], 'Maison Francis Kurkdjian - Baccarat Rouge 540') on conflict (id) do nothing;
