insert into public.products (id, name, conc, gender, family, tagline, description, notes, longevity, sillage, sizes, sample, look, badge, rank, added, stock, images, inspired) values ('arven', 'Arven', 'EDP', 'vyrams', 'sviezi', 'Bergamotė, pipirai ir ambroksanas', 'Gaivus ir galingas vyriškas kvapas. Sultinga Kalabrijos bergamotė ir pipirai atsiveria į levandą ir Sičuano pipirus, o ambroksanas ir kedras palieka ryškų, ilgai išliekantį šleifą. Universalus - darbui, laisvalaikiui ir vakarui.', '{"top":["Kalabrijos bergamotė","Pipirai"],"heart":["Sičuano pipirai","Levanda","Rožiniai pipirai","Vetiveris"],"base":["Ambroksanas","Kedras","Labdanas"]}'::jsonb, 4, 4, '[{"ml":33,"price":24.9},{"ml":100,"price":54.9}]'::jsonb, 3.9, '{"liquid":"#7FA3C9","tint":"#E6EDF4","cap":"gold","shape":"rect"}'::jsonb, null, 3, '2026-09-05', null, array['img/kvapai/arven-1.webp']::text[], 'Dior - Sauvage') on conflict (id) do nothing;
