insert into public.products (id, name, conc, gender, family, tagline, description, notes, longevity, sillage, sizes, sample, look, badge, rank, added, stock, images, inspired) values ('noirelle', 'Noirelle', 'EDP', 'moterims', 'gurmaniski', 'Tuberozė, kava ir kakava', 'Drąsus kontrastų kvapas. Migdolai ir kava susitinka su baltaisiais žiedais - tuberoze ir jazminu sambac, o tonkos pupelės, kakava ir vanilė suteikia gilumo ir jausmingumo. Šviesi ir tamsi pusė viename buteliuke.', '{"top":["Migdolai","Kava","Bergamotė","Citrina"],"heart":["Tuberozė","Jazminas sambac","Apelsino žiedai"],"base":["Tonkos pupelės","Kakava","Vanilė","Santalas"]}'::jsonb, 5, 4, '[{"ml":33,"price":24.9},{"ml":100,"price":54.9}]'::jsonb, 3.9, '{"liquid":"#5B3A6E","tint":"#EFE6F0","cap":"gold","shape":"rect"}'::jsonb, null, 4, '2026-09-10', null, array['img/kvapai/noirelle-1.webp']::text[], 'Carolina Herrera - Good Girl') on conflict (id) do nothing;
