insert into public.products (id, name, conc, gender, family, tagline, description, notes, longevity, sillage, sizes, sample, look, badge, rank, added, stock, images, inspired) values ('bellara', 'Bellara', 'EDP', 'moterims', 'gurmaniski', 'Irisas, pralinė ir vanilė', 'Saldus, švytintis kvapas. Juodieji serbentai ir kriaušė atsiveria į irisą, jazminą ir apelsino žiedus, o pralinė, vanilė, pačiulis ir tonkos pupelės sukuria minkštą, jaukų ir ilgai išliekantį pėdsaką. Kvapas džiaugsmui kasdien.', '{"top":["Juodieji serbentai","Kriaušė"],"heart":["Irisas","Jazminas","Apelsino žiedai"],"base":["Pralinė","Vanilė","Pačiulis","Tonkos pupelės"]}'::jsonb, 5, 4, '[{"ml":33,"price":24.9},{"ml":100,"price":54.9}]'::jsonb, 3.9, '{"liquid":"#D98BA0","tint":"#F8E9EC","cap":"gold","shape":"rect"}'::jsonb, null, 5, '2026-09-15', null, array['img/kvapai/bellara-1.webp']::text[], 'Lancôme - La Vie Est Belle') on conflict (id) do nothing;
insert into public.product_categories values ('bellara', 'ziemos-kolekcija') on conflict do nothing;
insert into public.products (id, name, conc, gender, family, tagline, description, notes, longevity, sillage, sizes, sample, look, badge, rank, added, stock, images, inspired) values ('ventor', 'Ventor', 'EDP', 'vyrams', 'medienos', 'Ananasas, beržo dūmas ir muskusas', 'Vaisinis ir dūminis medienos kvapas. Sultingas ananasas, bergamotė, juodieji serbentai ir obuolys atsiveria į beržą, pačiulį ir jazminą, o muskusas, ąžuolo samanos, ambra ir vanilė palieka užtikrintą, sodrų šleifą. Pasitikėjimo savimi kvapas.', '{"top":["Ananasas","Bergamotė","Juodieji serbentai","Obuolys"],"heart":["Beržas","Pačiulis","Marokietiškas jazminas","Rožė"],"base":["Muskusas","Ąžuolo samanos","Ambra","Vanilė"]}'::jsonb, 5, 4, '[{"ml":33,"price":29.9},{"ml":100,"price":59.9}]'::jsonb, 3.9, '{"liquid":"#6E7F4E","tint":"#ECEFE6","cap":"gold","shape":"rect"}'::jsonb, null, 6, '2026-09-20', null, array['img/kvapai/ventor-1.webp']::text[], 'Creed - Aventus') on conflict (id) do nothing;
insert into public.product_categories values ('ventor', 'vakarui') on conflict do nothing;
insert into public.products (id, name, conc, gender, family, tagline, description, notes, longevity, sillage, sizes, sample, look, badge, rank, added, stock, images, inspired) values ('lavelle', 'Lavelle', 'EDP', 'moterims', 'geliu', 'Levanda, apelsino žiedai ir vanilė', 'Laisvės kvapas. Prancūziška levanda ir mandarinas susipina su apelsino žiedais ir jazminu, o Madagaskaro vanilė, kedras ir ambra palieka drąsų, šiltą ir elegantišką pėdsaką. Moteriškas kvapas su charakteriu.', '{"top":["Levanda","Mandarinas","Juodieji serbentai"],"heart":["Apelsino žiedai","Jazminas"],"base":["Madagaskaro vanilė","Kedras","Ambra","Muskusas"]}'::jsonb, 4, 3, '[{"ml":33,"price":24.9},{"ml":100,"price":54.9}]'::jsonb, 3.9, '{"liquid":"#9C86C2","tint":"#EEE9F4","cap":"gold","shape":"rect"}'::jsonb, null, 7, '2026-10-01', null, array['img/kvapai/lavelle-1.webp']::text[], 'Yves Saint Laurent - Libre') on conflict (id) do nothing;
insert into public.products (id, name, conc, gender, family, tagline, description, notes, longevity, sillage, sizes, sample, look, badge, rank, added, stock, images, inspired) values ('aurum', 'Aurum', 'EDP', 'vyrams', 'ambros', 'Greipfrutas, cinamonas ir oda', 'Ryškus, saldžiai prieskoninis kvapas. Greipfrutas, mėta ir kraujo mandarinas suteikia energijos, rožė ir cinamonas - šilumos, o oda, ambra ir mediena palieka išraiškingą, įsimintiną šleifą. Vakarams, kai norisi būti pastebėtam.', '{"top":["Greipfrutas","Mėta","Kraujo mandarinas"],"heart":["Rožė","Cinamonas","Prieskoniai"],"base":["Oda","Ambra","Mediena","Pačiulis"]}'::jsonb, 4, 4, '[{"ml":33,"price":24.9},{"ml":100,"price":54.9}]'::jsonb, 3.9, '{"liquid":"#C99A3E","tint":"#F5EBD9","cap":"gold","shape":"rect"}'::jsonb, null, 8, '2026-10-10', null, array['img/kvapai/aurum-1.webp']::text[], 'Paco Rabanne - 1 Million') on conflict (id) do nothing;
