insert into public.products (id, name, conc, gender, family, tagline, description, notes, longevity, sillage, sizes, sample, look, badge, rank, added, stock, images, inspired) values ('azurin', 'Azurin', 'EDP', 'vyrams', 'medienos', 'Citrusai, smilkalai ir kedras', 'Elegantiškas, gaivus medienos kvapas. Greipfrutas, citrina ir mėta atsiveria į imbierą, muskato riešutą ir jazminą, o smilkalai, kedras ir santalas suteikia klasikinio, išrankaus gilumo. Tinka biurui, susitikimams ir vakarui.', '{"top":["Greipfrutas","Citrina","Mėta","Rožiniai pipirai"],"heart":["Imbieras","Muskato riešutas","Jazminas"],"base":["Smilkalai","Kedras","Santalas","Labdanas"]}'::jsonb, 4, 3, '[{"ml":33,"price":24.9},{"ml":100,"price":54.9}]'::jsonb, 3.9, '{"liquid":"#3E5F8C","tint":"#E4EAF2","cap":"gold","shape":"rect"}'::jsonb, 'Naujiena', 9, '2026-10-25', null, array['img/kvapai/azurin-1.webp']::text[], 'Chanel - Bleu de Chanel') on conflict (id) do nothing;
