insert into public.products (id, name, conc, gender, family, tagline, description, notes, longevity, sillage, sizes, sample, look, badge, rank, added, stock, images, inspired) values ('vialune', 'Vialune', 'EDP', 'moterims', 'geliu', 'Apelsino žiedai ir baltoji tuberozė', 'Švytintis baltųjų gėlių kvapas. Bergamotė ir apelsino žiedai atveria puokštę iš tuberozės ir indiško jazmino, kurią apgaubia Madagaskaro vanilė, baltasis muskusas ir kedras. Elegantiškas, šviesus ir moteriškas - kasdienai ir išskirtinėms akimirkoms.', '{"top":["Bergamotė","Apelsino žiedai"],"heart":["Tuberozė","Indiškas jazminas"],"base":["Madagaskaro vanilė","Baltasis muskusas","Kedras"]}'::jsonb, 4, 3, '[{"ml":33,"price":24.9},{"ml":100,"price":54.9}]'::jsonb, 3.9, '{"liquid":"#E2B9A6","tint":"#F7ECEF","cap":"gold","shape":"rect"}'::jsonb, 'Naujiena', 10, '2026-11-05', null, array['img/kvapai/vialune-1.webp']::text[], 'Giorgio Armani - My Way') on conflict (id) do nothing;
