insert into public.settings (id, data) values (1, '{"shop":"Vaidore","domain":"vaidore.com","tagline":"Prabangių kvapų įkvėpti Vaidore kvepalai. Pirma išbandykite 2 ml mėginuką.","currency":"eur","freeShippingFrom":60,"maxQty":10,"dispatch":"1-2 d. d.","returnDays":14,"hero":{"product":"vanor","eyebrow":"Žiemos kolekcija","title":"Vanor","text":"Tabakas, vanilė ir kakava - šilčiausias sezono kvapas."},"countries":["LT","LV","EE"],"shipping":[{"id":"omniva","name":"Omniva paštomatas","price":2.99,"days":"1-2 d. d."},{"id":"dpd","name":"DPD kurjeris iki durų","price":4.99,"days":"1-2 d. d."}],"company":{"name":"[Įmonės pavadinimas]","code":"[Įmonės kodas]","vat":"[PVM mokėtojo kodas]","address":"[Buveinės adresas]","email":"info@vaidore.com","phone":"[Telefonas]"},"story":{"title":"Mūsų istorija","text":"Vaidore gimė iš paprastos minties: kvapą reikia pažinti prieš jį perkant. Todėl kiekvieną kvapą siūlome ir 2 ml mėginuku, o natas aprašome taip, kad suprastumėte be parfumerio žodyno.","image":""},"discovery":{"id":"atradimu-rinkinys","name":"Atradimų rinkinys","count":5,"price":14.9,"text":"Bet kurie 5 kvapai po 2 ml - išbandykite namuose, ramiai."},"sampleCredit":{"days":30,"minOrder":39},"gift":{"price":2.5,"noteMax":200},"notifyForm":"","analytics":{"plausible":"","vercel":false},"inspired":{"show":true,"note":"Prekių ženklai priklauso jų savininkams. Vaidore su jais nesusijusi - pavadinimas nurodo tik kvapo kryptį."},"i18n":{"en":{"hero":{"eyebrow":"Winter collection","text":"Tobacco, vanilla and cocoa - the warmest scent of the season."},"story":{"title":"Our story","text":"Vaidore was born from a simple idea: you should get to know a fragrance before you buy it. That''s why every fragrance also comes as a 2 ml sample, and we describe the notes so that you don''t need a perfumer''s vocabulary to understand them."},"tagline":"Vaidore perfumes inspired by iconic luxury fragrances. Try a 2 ml sample first.","dispatch":"1-2 business days","inspired":{"note":"Trademarks belong to their respective owners. Vaidore is not affiliated with them - the name only indicates the direction of the fragrance."},"discovery":{"name":"Discovery set","text":"Any 5 fragrances in 2 ml - try them at home, at your own pace."},"shipping":{"omniva":{"name":"Omniva parcel locker","days":"1-2 business days"},"dpd":{"name":"DPD courier to your door","days":"1-2 business days"}},"rails":{"naujienos":{"title":"New in"},"moterims":{"title":"Perfume","line":"Inspired by the world''s most famous brands"},"q1m9ne":{"title":"Scented candles","line":"A cosy evening with a scented candle"},"unisex":{"title":"Fragrance oils","line":"For electric diffusers"},"vyrams":{"title":"Reed diffusers","line":"The easiest way to keep your home smelling good for longer"},"nuolaidos":{"title":"SALE","line":"Offers for a limited time only"}},"tiles":{"zvakes":{"title":"Candles"},"elektriniai-difuzoriai":{"title":"Electric diffusers"}},"topbar":{"free":{"text":"Free delivery over *€60*","short":"Free over *€60*"},"samples":{"text":"Every fragrance as a *2 ml sample* from €3.90","short":"*2 ml samples* from €3.90"},"dispatch":{"text":"Delivery in 2 days","short":"Dispatched within *1-2 business days*"},"credit":{"text":"Sample price *refunded* when you buy the bottle","short":"Sample price *refunded*"},"returns":{"text":"*14-day* returns · Secure payment","short":"*14-day* returns"}}}},"zones":[{"id":"lt","countries":["LT"],"freeFrom":60,"methods":[{"id":"omniva","carrier":"omniva","kind":"locker","price":2.99,"days":"1-2","perfume":true},{"id":"lpexpress","carrier":"lpexpress","kind":"locker","price":2.99,"days":"1-2","perfume":true},{"id":"dpd","carrier":"dpd","kind":"courier","price":4.99,"days":"1-2","perfume":true}]},{"id":"baltija","countries":["LV","EE"],"freeFrom":80,"methods":[{"id":"omniva","carrier":"omniva","kind":"locker","price":4.99,"days":"2-4","perfume":true},{"id":"dpd","carrier":"dpd","kind":"courier","price":7.99,"days":"2-4","perfume":true}]},{"id":"es1","countries":["PL","FI","DE","DK","SE","CZ","SK","AT","NL","BE","LU","FR"],"freeFrom":100,"methods":[{"id":"dpd","carrier":"dpd","kind":"courier","price":9.99,"days":"3-6","perfume":true}]},{"id":"es2","countries":["IE","IT","ES","PT","HU","SI","HR","RO","BG","GR"],"freeFrom":120,"methods":[{"id":"dpd","carrier":"dpd","kind":"courier","price":12.99,"days":"4-8","perfume":true}]},{"id":"salos","countries":["CY","MT"],"freeFrom":150,"methods":[{"id":"dpd","carrier":"dpd","kind":"courier","price":16.99,"days":"5-10","perfume":false}]},{"id":"jk","countries":["GB"],"freeFrom":150,"methods":[{"id":"dpd","carrier":"dpd","kind":"courier","price":14.99,"days":"4-7","perfume":true}]}]}'::jsonb) on conflict (id) do nothing;
