begin;
update public.products set i18n = '{"en":{"tagline":"Tobacco, vanilla and cocoa","description":"A rich, warm and luxurious fragrance. Tobacco leaf and spices open into creamy vanilla, cocoa and tonka bean, while dried fruits and woods leave a long, cosy trail. A fragrance for cold evenings and special occasions."}}'::jsonb where id = 'vanor';
update public.products set i18n = '{"en":{"tagline":"Saffron, jasmine and amber","badge":"New","description":"A radiant amber-woody fragrance. Saffron and jasmine blend with amberwood and amber, while fir resin and cedar give it air, light and a distinctive, long-lasting trail. A fragrance others notice."}}'::jsonb where id = 'safrane';
update public.products set i18n = '{"en":{"tagline":"Bergamot, pepper and ambroxan","description":"A fresh and powerful masculine fragrance. Juicy Calabrian bergamot and pepper open into lavender and Sichuan pepper, while ambroxan and cedar leave a bold, long-lasting trail. Versatile - for work, leisure and evenings."}}'::jsonb where id = 'arven';
update public.products set i18n = '{"en":{"tagline":"Tuberose, coffee and cocoa","description":"A bold fragrance of contrasts. Almond and coffee meet white flowers - tuberose and jasmine sambac - while tonka bean, cocoa and vanilla add depth and sensuality. A light and a dark side in one bottle."}}'::jsonb where id = 'noirelle';
update public.products set i18n = '{"en":{"tagline":"Iris, praline and vanilla","description":"A sweet, radiant fragrance. Blackcurrant and pear open into iris, jasmine and orange blossom, while praline, vanilla, patchouli and tonka bean create a soft, cosy and long-lasting trail. A fragrance for everyday joy."}}'::jsonb where id = 'bellara';
update public.products set i18n = '{"en":{"tagline":"Pineapple, birch smoke and musk","description":"A fruity, smoky woody fragrance. Juicy pineapple, bergamot, blackcurrant and apple open into birch, patchouli and jasmine, while musk, oakmoss, amber and vanilla leave a confident, rich trail. The scent of self-confidence."}}'::jsonb where id = 'ventor';
update public.products set i18n = '{"en":{"tagline":"Lavender, orange blossom and vanilla","description":"The scent of freedom. French lavender and mandarin intertwine with orange blossom and jasmine, while Madagascar vanilla, cedar and amber leave a bold, warm and elegant trail. A feminine fragrance with character."}}'::jsonb where id = 'lavelle';
update public.products set i18n = '{"en":{"tagline":"Grapefruit, cinnamon and leather","description":"A vivid, sweet-spicy fragrance. Grapefruit, mint and blood mandarin bring energy, rose and cinnamon add warmth, while leather, amber and woods leave an expressive, memorable trail. For evenings when you want to be noticed."}}'::jsonb where id = 'aurum';
update public.products set i18n = '{"en":{"tagline":"Citrus, incense and cedar","badge":"New","description":"An elegant, fresh woody fragrance. Grapefruit, lemon and mint open into ginger, nutmeg and jasmine, while incense, cedar and sandalwood add classic, refined depth. For the office, meetings and evenings."}}'::jsonb where id = 'azurin';
update public.products set i18n = '{"en":{"tagline":"Orange blossom and white tuberose","badge":"New","description":"A radiant white-floral fragrance. Bergamot and orange blossom open a bouquet of tuberose and Indian jasmine, wrapped in Madagascar vanilla, white musk and cedar. Elegant, bright and feminine - for every day and special moments."}}'::jsonb where id = 'vialune';
update public.families set i18n = '{"en":{"name":"Floral","hint":"Rose, jasmine, peony"}}'::jsonb where id = 'geliu';
update public.families set i18n = '{"en":{"name":"Fresh","hint":"Citrus, marine, green notes"}}'::jsonb where id = 'sviezi';
update public.families set i18n = '{"en":{"name":"Woody","hint":"Cedar, sandalwood, vetiver"}}'::jsonb where id = 'medienos';
update public.families set i18n = '{"en":{"name":"Amber","hint":"Amber, incense, spices"}}'::jsonb where id = 'ambros';
update public.families set i18n = '{"en":{"name":"Gourmand","hint":"Vanilla, honey, cocoa"}}'::jsonb where id = 'gurmaniski';
update public.categories set i18n = '{"en":{"name":"Winter collection","description":"Warm, deep fragrances for cold evenings."}}'::jsonb where id = 'ziemos-kolekcija';
update public.categories set i18n = '{"en":{"name":"Summer freshness","description":"Light, fresh fragrances for warm days."}}'::jsonb where id = 'vasaros-gaiva';
update public.categories set i18n = '{"en":{"name":"For the evening","description":"Bolder fragrances for evenings and celebrations."}}'::jsonb where id = 'vakarui';
